import{_ as t,o as d,c as o,a0 as r}from"./chunks/framework.CNXp-E7Q.js";const p=JSON.parse('{"title":"Crate scope audit — bupha under ADR-0006","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/crate-scope-audit.md","filePath":"explanation/crate-scope-audit.md"}'),s={name:"explanation/crate-scope-audit.md"};function c(a,e,i,n,h,u){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="crate-scope-audit-—-bupha-under-adr-0006" tabindex="-1">Crate scope audit — bupha under ADR-0006 <a class="header-anchor" href="#crate-scope-audit-—-bupha-under-adr-0006" aria-label="Permalink to &quot;Crate scope audit — bupha under ADR-0006&quot;">​</a></h1><p>Per-crate ruling for every crate in <code>crates/</code>, against ADR-0006 (&quot;bupha is CI semantics only — substrate is hypha/peregrin, distribution is tamias&quot;) and the P-002 ci-job ops contract.</p><p>Rulings:</p><ul><li><strong>KEEP</strong> — CI semantics or runner/dialect/forge/status knowledge that stays in bupha.</li><li><strong>MIGRATE</strong> — stateful/infra machinery that becomes a hypha-side impl or dies in favor of ci-job entities. Target home noted.</li><li><strong>DIE</strong> — fully subsumed, no port value.</li><li><strong>SPLIT</strong> — crate mixes semantics + machinery; noted per half.</li><li><strong>DEV</strong> — survives only as the in-process dev/test harness (ADR-0006: &quot;ports stay, impls get swapped&quot;).</li></ul><h2 id="the-table" tabindex="-1">The table <a class="header-anchor" href="#the-table" aria-label="Permalink to &quot;The table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Crate</th><th>Ruling</th><th>Reason</th><th>Target home</th></tr></thead><tbody><tr><td><code>bupha-core</code></td><td>KEEP</td><td>Canonical job spec, <code>Queue</code>/<code>QueuePolicy</code>/<code>MAX_PENDING</code>, <code>is_valid_sha</code>/<code>is_valid_key</code>, <code>WatchedRepo</code>, config types — the pure semantics P-002 pins as the plane&#39;s spec. Gains <code>cijob</code> transition functions.</td><td>stays</td></tr><tr><td><code>bupha-access</code></td><td>KEEP</td><td>&quot;Who may trigger&quot; — sender authorization is ingest semantics; <code>sender</code> is forge-attested.</td><td>stays</td></tr><tr><td><code>bupha-access-file</code></td><td>KEEP</td><td>Allowlist policy impl — CI-ingress policy, not generic infra.</td><td>stays</td></tr><tr><td><code>bupha-access-forge</code></td><td>KEEP</td><td>Forge collaborator-permission check — forge knowledge is bupha&#39;s.</td><td>stays</td></tr><tr><td><code>bupha-attest</code></td><td>KEEP</td><td>Run-provenance port (SLSA-style predicate) — attestation is a CI deliverable.</td><td>stays</td></tr><tr><td><code>bupha-attest-file</code></td><td>KEEP</td><td>Predicate-file impl of <code>Attest</code>.</td><td>stays</td></tr><tr><td><code>bupha-attest-sigstore</code></td><td>KEEP</td><td>cosign-signed predicate impl.</td><td>stays</td></tr><tr><td><code>bupha-audit-file</code></td><td>KEEP</td><td>JSONL audit of access/run decisions — CI observability. Optional feature; the ci-job entity index may subsume it in hosted mode (open question).</td><td>stays</td></tr><tr><td><code>bupha-cache</code></td><td>KEEP</td><td>Port only <em>renders conf text</em> the runner consumes (sccache is external) — runner-facing semantics, not a stateful cache. The worktree/build cache concern belongs to substrate, but this crate never held state.</td><td>stays</td></tr><tr><td><code>bupha-cache-sccache</code></td><td>KEEP</td><td>Conf renderer for sccache-compatible backends.</td><td>stays</td></tr><tr><td><code>bupha-cli</code></td><td>SPLIT/DEV</td><td>Per ADR-0006 amendment there is no user-facing <code>bupha</code> CLI. <code>watch</code>/<code>worker</code>/<code>agent</code>/<code>run</code>/<code>import</code>/<code>doctor</code> survive as the dev/test harness (single-box <code>bupha-node</code> + embedded queue); lifecycle verbs (<code>deploy</code>/<code>service</code>/<code>destroy</code>) are already driver/tamias surface. The binary eventually dissolves into <code>tamias-driver-bupha worker</code> + a dev binary.</td><td>dev binary + driver</td></tr><tr><td><code>bupha-cloudflared</code></td><td>MIGRATE</td><td>Named/quick tunnel provider — generic ingress plumbing. Webhook ingress is peregrin&#39;s (P-002/T-055); tunnel lifecycle is hypha-service territory.</td><td>hypha tunnel impl (or dies if peregrin ships one)</td></tr><tr><td><code>bupha-config</code></td><td>KEEP</td><td>Config port over the CI fleet/repo model — domain-shaped, not generic config machinery.</td><td>stays</td></tr><tr><td><code>bupha-config-file</code></td><td>KEEP</td><td>Path resolution + syntax dispatch.</td><td>stays</td></tr><tr><td><code>bupha-config-toml</code></td><td>KEEP</td><td>TOML parser impl.</td><td>stays</td></tr><tr><td><code>bupha-config-yaml</code></td><td>KEEP</td><td>YAML parser impl (<code>fleet.toml</code>/<code>bupha.yaml</code> are the standard).</td><td>stays</td></tr><tr><td><code>bupha-container</code></td><td>KEEP</td><td>Runner impl — unprivileged container exec is CI-runner semantics.</td><td>stays</td></tr><tr><td><code>bupha-dagger</code></td><td>KEEP</td><td>Runner impl — <code>dagger call</code> per job.</td><td>stays</td></tr><tr><td><code>bupha-dotenv</code></td><td>MIGRATE</td><td><code>KEY=VAL</code> secret file — generic secret plumbing, not CI semantics. hypha already ships <code>hypha-dotenv</code>; under a cuora story (T-056) it dies outright.</td><td>hypha-secret impls / cuora (T-056)</td></tr><tr><td><code>bupha-driver</code></td><td>KEEP+EXTEND</td><td><code>tamias-driver-bupha</code> is the distribution surface <em>and</em> the future worker host (P-002 §4 <code>worker</code> verb). <code>data.rs</code> moves from <code>queue.redb</code> reads to the ci-job entity index when hosted mode lands.</td><td>stays — gains <code>worker</code> verb + ci-jobs view</td></tr><tr><td><code>bupha-gha</code></td><td>KEEP</td><td>The workflow dialect — parse/plan/script/executor for <code>.github/workflows/*.yml</code>. Core CI semantics; also feeds T-050 (self-hosted GHA runner — reserved name <code>gha-runner</code>, T-054).</td><td>stays</td></tr><tr><td><code>bupha-git</code></td><td>KEEP</td><td><code>Vcs</code> impl via git CLI — worktree/sync primitives every runner needs.</td><td>stays</td></tr><tr><td><code>bupha-github</code></td><td>KEEP</td><td>Trigger parse/verify (push normalization) + <code>StatusSink</code> commit-status posting — both halves are CI semantics (P-002 keeps normalization + worker-side status posting in bupha).</td><td>stays</td></tr><tr><td><code>bupha-history</code></td><td>KEEP (dev/optional)</td><td>JSONL run records for <code>bupha runs</code>/<code>log</code>. In hosted mode the ci-job entity index <em>is</em> the history; keep as dev-mode/optional feature, candidate to fold later.</td><td>stays (dev)</td></tr><tr><td><code>bupha-http</code></td><td>KEEP</td><td>Runner impl — remote exec via <code>bupha agent</code> (tar worktree + poll). Runner semantics; known auth caveats tracked as issues.</td><td>stays</td></tr><tr><td><code>bupha-keyring</code></td><td>MIGRATE</td><td>OS-keyring secret impl — generic secret plumbing. hypha ships <code>hypha-keyring</code>; cuora is the org broker story (T-056).</td><td>hypha-keyring / cuora (T-056)</td></tr><tr><td><code>bupha-queue</code></td><td>KEEP (dev only)</td><td><code>QueueStore</code>/<code>WorkQueue</code> port + <code>MemWorkQueue</code> — P-002 keeps the port and in-process impl for dev/test; the distributed path is the ci-job entity plane, not this port.</td><td>stays (dev/test)</td></tr><tr><td><code>bupha-queue-lease</code></td><td>DIE</td><td><code>Fence</code>/<code>TryClaim</code> semantics are absorbed verbatim into the ci-job entity (<code>fence</code> counter + <code>leaseExpiresAt</code> + <code>ci.claim</code> CAS, P-002 §3). No port value once the plane lands; dev mode doesn&#39;t need it (<code>MemWorkQueue</code> always claims).</td><td>→ <code>bupha-plane</code> entity state</td></tr><tr><td><code>bupha-queue-redb</code></td><td>MIGRATE</td><td>Embedded durable queue — single-node state machinery. The entity plane replaces it even single-box; if hypha wants a local durable queue impl it can adopt the redb code hypha-side. Dev path uses <code>MemWorkQueue</code>.</td><td>hypha-side queue impl (or DIE — open question)</td></tr><tr><td><code>bupha-queue-redis</code></td><td>MIGRATE</td><td>Networked queue impl (SET NX claim + INCR fence) — textbook substrate. The ci-job entity CAS + outbox is the distributed queue.</td><td>hypha-side queue impl</td></tr><tr><td><code>bupha-runner</code></td><td>KEEP</td><td>Runner port — <code>RunCtx</code>/<code>RunHandle</code>/<code>Runner</code> is the seam every runner impl (shell/container/ssh/http/dagger/gha) plugs into.</td><td>stays</td></tr><tr><td><code>bupha-secret</code></td><td>DECIDE (T-056)</td><td>Secret-resolution port. If cuora wins the secrets story the port dies (cuora refs replace named-secret lookup); if env-file/keyring survives it stays thin. Tentative: DIE under cuora.</td><td>cuora / hypha-secret (T-056)</td></tr><tr><td><code>bupha-service</code></td><td>DIE</td><td>OS service-lifecycle port — generic infra now owned by tamias-provider (<code>tamias-deploy -systemd</code>/<code>-windows</code>) and hypha-service. Bupha&#39;s only consumer was its own (dead) CLI verbs.</td><td>tamias / hypha-service</td></tr><tr><td><code>bupha-shell</code></td><td>KEEP</td><td>Runner impl — <code>bash -c</code> exec.</td><td>stays</td></tr><tr><td><code>bupha-ssh</code></td><td>KEEP</td><td>Runner impl — remote exec over ssh/rsync. Runner semantics.</td><td>stays</td></tr><tr><td><code>bupha-status</code></td><td>KEEP</td><td><code>StatusSink</code> port — workers post forge commit statuses on <code>ci.complete</code> (they hold forge creds via <code>token_env</code>); the plane records outcome but does not post (P-002 §5).</td><td>stays</td></tr><tr><td><code>bupha-sturn</code></td><td>KEEP</td><td>Trigger impl — polls <code>refs/sturn/*</code> WAL → normalized <code>Push</code>es with SSH-verified sender attestation. Event→push normalization is CI semantics; sturn itself is a sibling repo.</td><td>stays</td></tr><tr><td><code>bupha-systemd</code></td><td>MIGRATE</td><td>User-unit rendering — generic service lifecycle. <code>tamias-deploy -systemd</code> already owns this; the driver&#39;s <code>deploy</code> verb should consume tamias&#39;s surface instead.</td><td>tamias-deploy-systemd / hypha-systemd</td></tr><tr><td><code>bupha-telemetry</code></td><td>KEEP</td><td>Telemetry port over CI-shaped run events (<code>Queued</code>/<code>Started</code>/<code>Finished</code>) — observability semantics; optional feature.</td><td>stays</td></tr><tr><td><code>bupha-telemetry-otel</code></td><td>KEEP</td><td>OpenMetrics textfile impl. Note overlap with <code>hypha-telemetry</code> (OTLP) — different export shape, both may coexist; revisit if hypha-telemetry gains textfile.</td><td>stays</td></tr><tr><td><code>bupha-trigger</code></td><td>KEEP</td><td>Source/<code>Trigger</code> port + <code>Push</code>/<code>Verdict</code>/<code>PushOutcome</code> — the normalization contract every ingress (webhook, sturn, future gitlab) drives.</td><td>stays</td></tr><tr><td><code>bupha-tunnel</code></td><td>DIE</td><td>Port exists solely to expose the webhook listener publicly. Production ingress is peregrin&#39;s; dev mode can use a hypha tunnel impl or <code>direct</code>. No CI semantics in the trait.</td><td>→ hypha (if a generic tunnel port is wanted)</td></tr><tr><td><code>bupha-vcs</code></td><td>KEEP</td><td>VCS port — sync/worktree/tag ops the runner pipeline needs.</td><td>stays</td></tr><tr><td><code>bupha-webhook</code></td><td>SPLIT</td><td>The <code>Trigger</code>-driving + signature/dedup logic&#39;s durable value is subsumed: deterministic entity ids (<code>ci:{key}:{sha}:{attempt}</code>) dedup replays for free (P-002 §1), so the <code>Seen</code> ring dies with the listener. The tiny_http accept-loop harness → dev-mode only; production ingress is a peregrin campaign listener that normalizes via <code>bupha-trigger</code> then <code>POST /api/entities</code> (T-055).</td><td>harness → dev; dedup → entity ids</td></tr></tbody></table><h2 id="incoming" tabindex="-1">Incoming <a class="header-anchor" href="#incoming" aria-label="Permalink to &quot;Incoming&quot;">​</a></h2><ul><li><strong><code>bupha-plane</code></strong> (new, P-002) — KEEP. Thin <code>hypha_http::EntityPlane</code> adapter holding ci-job entity state and dispatching <code>ci.*</code> ops; the pure transition math stays in <code>bupha-core</code>. First bupha→hypha dep — confirm acceptable (P-002 open question 1).</li></ul><h2 id="key-judgment-calls" tabindex="-1">Key judgment calls <a class="header-anchor" href="#key-judgment-calls" aria-label="Permalink to &quot;Key judgment calls&quot;">​</a></h2><ul><li><strong>Queue family</strong>: the <em>semantics</em> (<code>Queue</code>, supersede/retry math, <code>MAX_PENDING</code>) stay in <code>bupha-core</code> as the spec the plane mirrors; the <em>port + in-process impl</em> (<code>bupha-queue</code>) stay for dev/test per P-002; the <em>distributed impls</em> (<code>-redb</code>, <code>-redis</code>) and the <em>lease port</em> migrate/die — fencing becomes entity state (<code>fence</code> + <code>leaseExpiresAt</code> + op CAS), not a separate port.</li><li><strong>Cache</strong>: <code>bupha-cache</code>/<code>-sccache</code> are KEEP — they render runner conf, they don&#39;t <em>are</em> a cache. The substrate cache concern (worktree/build artifacts across nodes) is hypha&#39;s and was never these crates&#39; job.</li><li><strong>Ingress trio</strong> (<code>webhook</code>/<code>trigger</code>/<code>sturn</code>): normalization (<code>Trigger</code>, <code>Push</code>, <code>Verdict</code>, sturn WAL→push) is KEEP — it&#39;s the &quot;forge event → job spec&quot; half of ADR-0006. Listener harnesses are dev-mode; production ingress is peregrin&#39;s.</li><li><strong>Secrets trio</strong> (<code>secret</code>/<code>keyring</code>/<code>dotenv</code>): judged generic infra, not CI semantics — but the ruling is gated on T-056 (cuora vs env vs keyring). hypha already ships <code>hypha-{secret,keyring,dotenv}</code> impls, so MIGRATE has a ready home; under cuora they all DIE.</li><li><strong>Service/lifecycle</strong> (<code>service</code>/<code>systemd</code>/<code>tunnel</code>/<code>cloudflared</code>): all generic host machinery — tamias (deploy/provider) + hypha (service/systemd) own it now. DIE or MIGRATE; nothing here is CI semantics.</li><li><strong>Enterprise surfaces</strong> (<code>access*</code>/<code>attest*</code>/<code>audit-file</code>/<code>history</code>/ <code>telemetry*</code>): KEEP as optional bupha features — they encode CI-specific policy (who may trigger, run provenance, audit trail), not generic substrate. Only <code>history</code> is a maybe-fold into the entity index later.</li><li><strong><code>bupha-cli</code></strong>: SPLIT — dev harness survives, user-facing binary dies per the ADR-0006 amendment; <code>tamias-driver-bupha worker</code> is the production worker host.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ol><li><strong>Secrets story (T-056)</strong> gates <code>bupha-secret</code>/<code>-keyring</code>/<code>-dotenv</code>: cuora → all three die; env/keyring → port stays thin, impls duplicate hypha&#39;s. Pick before migrating.</li><li><strong><code>bupha-queue-redb</code></strong>: migrate the redb code hypha-side as a local durable queue impl, or let the entity plane cover single-box too (dev uses <code>MemWorkQueue</code>) and DIE it? Lean: DIE unless hypha wants a non-entity queue.</li><li><strong><code>bupha-plane</code> home</strong> (P-002 Q1): bupha crate dep&#39;ing on <code>hypha-http</code> vs plane code inside <code>peregrin-node</code>. Audit assumes the bupha crate.</li><li><strong><code>history</code>/<code>audit-file</code> vs entity index</strong>: do ci-job entities + <code>ci.status</code> fully replace <code>history.jsonl</code>/<code>audit.log</code> in hosted mode, making both dev-only? Probably yes; confirm before deleting read paths the driver still uses.</li><li><strong><code>bupha-telemetry-otel</code> vs <code>hypha-telemetry</code></strong>: keep the OpenMetrics textfile impl in bupha, or does hypha-telemetry absorb textfile export? Different export shapes today — keep for now.</li><li><strong>Tunnel</strong>: does hypha/peregrin want a generic tunnel port at all, or is ingress exposure always a campaign/deploy concern (named tunnel via tamias)? Determines whether <code>bupha-tunnel</code>&#39;s trait migrates or just dies.</li></ol><h2 id="resolution-—-t-077-landed" tabindex="-1">Resolution — T-077 (landed) <a class="header-anchor" href="#resolution-—-t-077-landed" aria-label="Permalink to &quot;Resolution — T-077 (landed)&quot;">​</a></h2><p>With T-055 (ADR-0007: ingress is peregrin-owned, bupha webhook surfaces are standalone/dev mode) and T-056 (cuora canonical, T-059 migration verified) done, the remaining MIGRATE/DIE crates were retired in three commits on <code>main</code>:</p><table tabindex="0"><thead><tr><th>Crate</th><th>Outcome</th></tr></thead><tbody><tr><td><code>bupha-secret</code></td><td><strong>DIE</strong> — trait identical to <code>hypha_secret::Secrets</code>; consumers take the hypha git dep directly.</td></tr><tr><td><code>bupha-keyring</code></td><td><strong>DIE → <code>hypha-keyring</code></strong> with <code>service = &quot;bupha&quot;</code> so pre-cuora keyring entries still resolve.</td></tr><tr><td><code>bupha-dotenv</code></td><td><strong>DIE → <code>hypha-dotenv</code></strong> — <code>~/.config/bupha/env</code> path/format unchanged.</td></tr><tr><td><code>bupha-secret-cuora</code></td><td><strong>KEEP</strong> — the canonical store; now implements <code>hypha_secret::Secrets</code> (already wrapped <code>hypha-secret-cuora</code>).</td></tr><tr><td><code>bupha-service</code></td><td><strong>DIE</strong> — one impl (<code>bupha-systemd</code>), consumers used free fns/struct, not the trait.</td></tr><tr><td><code>bupha-systemd</code></td><td><strong>DIE → <code>hypha-systemd</code></strong> — unit render/control via <code>write_unit</code>/<code>enable</code>/<code>disable</code>/<code>status</code>/<code>restart</code>/<code>unit_path</code>/<code>default_unit_dir</code>. Bupha-shaped helpers (<code>write_env_skeleton</code>, <code>service_logs</code>, strict daemon-reload on destroy, <code>SystemdService</code> wrapper) folded into <code>bupha-cli</code>&#39;s <code>deploy</code> module. Unit diffs: bare name + <code>.service</code> suffix, quoted ExecStart argv, <code>EnvironmentFile=-</code>, <code>Restart=on-failure</code>.</td></tr><tr><td><code>bupha-tunnel</code> + <code>bupha-cloudflared</code></td><td><strong>FOLDED → <code>bupha-watch::tunnel</code></strong> — ADR-0007 keeps them as the standalone/dev-mode ingress; no hypha tunnel impl exists or is wanted (ingress exposure is a deploy/campaign concern).</td></tr><tr><td><code>bupha-webhook</code></td><td><strong>FOLDED → <code>bupha-watch::webhook</code></strong> — same reasoning; <code>tiny_http</code> dep moved to bupha-watch.</td></tr></tbody></table><p>Open questions 1 and 6 are thereby resolved: cuora won the secrets story (legacy keyring/dotenv legs survive only as hypha-backed fallbacks in the dev chain), and no generic tunnel port migrates — the trait lives on inside <code>bupha-watch</code> for standalone mode only.</p>',16)])])}const m=t(s,[["render",c]]);export{p as __pageData,m as default};
